## Code Example

```c
// Minimal SP/SC enqueue skeleton
#include <stdatomic.h>
#define N 128
typedef struct { int data; } item_t;
typedef struct { item_t buf[N]; _Atomic size_t head, tail; } queue_t;
int enqueue(queue_t *q, item_t it){
  size_t h = atomic_load_explicit(&q->head, memory_order_relaxed);
  size_t t = atomic_load_explicit(&q->tail, memory_order_acquire);
  if ((h + 1) % N == t) return -1; // full
  q->buf[h % N] = it;
  atomic_store_explicit(&q->head, h+1, memory_order_release);
  return 0;
}
```

